solution.code:
function zip(a, b) {
  var length = Math.min(a.length, b.length);
  var pairs = [];
  for (var i = 0; i < length; i++) {
    pairs.push([a[i], b[i]]);
  }
  return pairs;
}

console.log(zip([1, 2, 3], ["x"]));
